outv=[r.copy() for r in grid]
for c in range(len(grid[0])):
    inds=[r for r in range(len(grid)) if grid[r][c]==2]
    for a,b in zip(inds,inds[1:]):
        for rr in range(a+1,b):
            if outv[rr][c]==0: outv[rr][c]=3
print('\n'.join(' '.join(map(str,r)) for r in outv))

